import {unitFaction,factionImage} from './factions.js';
import {isLeader,unitResources} from './unit-info.js';
import {tierLabel,numericRating} from './math.js';
// PRTS tactical overlays. This module reads render events only; it never touches game state.
export const MEMES={
 AK097:{button:'C',title:'799',line:'你知道满配丰神二技能如果打二，然后打0~2重的小兵DPS是多少啊，只有799啊',style:'hunter'},
 AK086:{button:'B',title:'苹果派！',line:'弹幕已送达。',style:'barrage'},
 AK150:{buttons:['A','B','C'],title:'我无',lines:['形不成形……','千招百式……','劲发江潮落……','你们解决问题……'],style:'chongyue'},
 AK055:{button:'B',title:'莱万汀',line:'汀！汀！莱万汀！',style:'surtr'},
 AK019:{button:'C',title:'辉煌裂片',line:'力量回来了一点，不多，但够用',style:'passenger'}
};
export function memeFor(e){const m=MEMES[e?.card];if(!m||e.side!=='ally'||!(m.buttons||[m.button]).includes(e.button))return null;if(e.card==='AK055'&&!e.twilightEntered)return null;if(e.card==='AK019'&&!(e.refundEnergy>0||e.refundFragments>0))return null;return m;}
export const ART_MOTION={AK006:'meteor',AK009:'stitch',AK011:'flow',AK012:'heat',AK014:'clock',AK029:'circuit',AK095:'barrage',AK097:'hunter',AK192:'contract',AK195:'orbit',AK215:'verdict',AK221:'fold'};
const colorFor=e=>/国度|国境|描躯/.test(e.label)?'#c7829c':/灼|熔|陨|火/.test(e.label)?'#f2b367':e.attack?'#90d9e4':'#a7d4bd';
let seenLeaders=new Set(),lastResources=new Map();
let root,canvas,cx,raf=0,particles=[],lastBattle=null,lastAction=-1,lastPhase='',lastBurst=0,lastFallen=false,lastResolved=false;
const reduced=()=>localStorage.getItem('terra-ui-motion')==='reduced'||localStorage.getItem('terra-ui-motion')!=='full'&&matchMedia('(prefers-reduced-motion: reduce)').matches;
function ensure(){if(root)return;root=document.createElement('div');root.id='prts-motion';root.setAttribute('aria-hidden','true');root.innerHTML='<canvas></canvas><div class="prts-cue"></div><div class="prts-meme"></div><div class="prts-outcome"><div class="outcome-grid"></div><div class="outcome-seal"><img src="assets/prts/factions/rhodes.png" alt=""></div><div class="outcome-copy"><small></small><strong></strong><span></span></div><div class="outcome-index">PRTS<br>FIELD / 01</div></div>';document.body.append(root);canvas=root.querySelector('canvas');cx=canvas.getContext('2d');}
function cue(title,line,kind=''){ensure();const el=root.querySelector('.prts-cue');el.className='prts-cue '+kind;el.replaceChildren();const small=document.createElement('small'),strong=document.createElement('strong'),sub=document.createElement('span');small.textContent='PRTS / OPERATION';strong.textContent=title;sub.textContent=line;el.append(small,strong,sub);el.animate([{opacity:0,transform:'translateX(-12px)'},{opacity:1,transform:'translateX(0)',offset:.12},{opacity:1,offset:.8},{opacity:0}],{duration:reduced()?600:1900,fill:'both'});}
function outcome(title,line,kind='success'){ensure();const el=root.querySelector('.prts-outcome');el.className='prts-outcome '+kind;el.querySelector('small').textContent=kind==='opening'?'RHODES ISLAND / OPERATIONS':kind==='success'?'OPERATION ACCOMPLISHED':'TERMINAL RECORD';el.querySelector('strong').textContent=title;el.querySelector('span').textContent=line;el.getAnimations().forEach(a=>a.cancel());el.animate(reduced()?[{opacity:0},{opacity:1,offset:.12},{opacity:1,offset:.8},{opacity:0}]:[{opacity:0,clipPath:'inset(0 100% 0 0)',transform:'translate(-50%,8px)'},{opacity:1,clipPath:'inset(0)',transform:'translate(-50%,0)',offset:.24},{opacity:1,offset:.8},{opacity:0}],{duration:reduced()?500:kind==='opening'?1200:850,fill:'both'});}
let memeTimer=null,memeGeneration=0;
function placeMeme(){const el=root?.querySelector('.prts-meme');if(!el?.classList.contains('docked'))return;const r=document.querySelector('.battle-subtitles')?.getBoundingClientRect();if(r){el.style.left=r.left+'px';el.style.right='auto';el.style.top=r.top+'px';el.style.width=r.width+'px';el.style.height=r.height+'px';}}
function clearMeme(){clearTimeout(memeTimer);memeGeneration++;const el=root?.querySelector('.prts-meme');el?.getAnimations().forEach(a=>a.cancel());el?.replaceChildren();if(el)el.style.opacity='0';}
function meme(m){clearMeme();if(localStorage.getItem('terra-ui-memes')==='off')return;const el=root.querySelector('.prts-meme');el.removeAttribute('style');el.className='prts-meme '+m.style+(['chongyue','surtr','passenger'].includes(m.style)?' docked':'');const s=document.createElement('small'),t=document.createElement('strong'),p=document.createElement('p');s.textContent='技能彩蛋';t.textContent=m.title;p.textContent=m.line||'';el.append(s,t,p);placeMeme();const generation=memeGeneration;
 if(m.lines){const track=document.createElement('div');track.className='chant-track';p.remove();el.append(track);let index=0;const next=()=>{if(generation!==memeGeneration)return;const line=document.createElement('p');line.textContent=m.lines[index%m.lines.length];track.append(line);while(track.children.length>3)track.firstElementChild.remove();if(!reduced())line.animate([{opacity:0,transform:'translateX(9px)'},{opacity:1,transform:'translateX(0)'}],{duration:180});s.textContent='技能连播 / '+String(index+1).padStart(2,'0');index++;if(index<8)memeTimer=setTimeout(next,850);};next();}
 if(m.style==='surtr'){const beats=document.createElement('div');beats.className='surtr-beats';for(let i=0;i<3;i++){const beat=document.createElement('i');beat.style.setProperty('--beat',i);beats.append(beat);}el.append(beats);}
 el.animate(reduced()?[{opacity:1},{opacity:1,offset:.92},{opacity:0}]:[{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)',offset:.04},{opacity:1,offset:.92},{opacity:0}],{duration:m.lines?7600:reduced()?2200:3600,fill:'both'});}
function bounds(id){const el=[...document.querySelectorAll('[data-act^="target:"]')].find(e=>e.dataset.act==='target:'+id);if(!el)return null;const r=el.getBoundingClientRect();return{x:r.left+r.width/2,y:r.top+r.height/2,w:r.width,h:r.height};}
function frame(now){const dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==innerWidth*dpr||canvas.height!==innerHeight*dpr){canvas.width=innerWidth*dpr;canvas.height=innerHeight*dpr;canvas.style.width=innerWidth+'px';canvas.style.height=innerHeight+'px';}cx.setTransform(dpr,0,0,dpr,0,0);cx.clearRect(0,0,innerWidth,innerHeight);particles=particles.filter(p=>now-p.born<p.life);for(const p of particles){const age=(now-p.born)/p.life;cx.strokeStyle=p.color;cx.lineWidth=p.bold?2:1;cx.globalAlpha=(1-age)*.75;if(p.kind==='shot'){const q=Math.min(1,age*1.8),x=p.x+(p.tx-p.x)*q,y=p.y+(p.ty-p.y)*q;cx.shadowColor=p.color;cx.shadowBlur=12;cx.lineWidth=3;cx.beginPath();cx.moveTo(x-(p.tx-p.x)*.1,y-(p.ty-p.y)*.1);cx.lineTo(x,y);cx.stroke();cx.shadowBlur=0;}else if(p.kind==='bolt'){for(let i=0;i<3;i++){const r=(15+i*12)*(1+age);cx.strokeRect(p.x-r,p.y-r,r*2,r*2);}}else if(p.kind==='ray'){let q=Math.min(1,age*3);cx.beginPath();cx.moveTo(p.x,p.y);cx.lineTo(p.x+(p.tx-p.x)*q,p.y+(p.ty-p.y)*q);cx.stroke();}else if(p.kind==='clock'||p.kind==='orbit'){let r=22+age*38;cx.beginPath();cx.arc(p.x,p.y,r,age*4,age*4+Math.PI*1.7);cx.stroke();for(let i=0;i<12;i++){let a=i*Math.PI/6;cx.beginPath();cx.moveTo(p.x+Math.cos(a)*(r-4),p.y+Math.sin(a)*(r-4));cx.lineTo(p.x+Math.cos(a)*r,p.y+Math.sin(a)*r);cx.stroke();}let a=p.kind==='clock'?-age*9:age*6;cx.beginPath();cx.moveTo(p.x,p.y);cx.lineTo(p.x+Math.cos(a)*r*.8,p.y+Math.sin(a)*r*.8);cx.stroke();}else if(p.kind==='heat'){for(let i=0;i<4;i++){let y=p.y-24+i*16,x=p.x-60+age*110;cx.strokeRect(x,y,110*(1-age),3);}}else if(p.kind==='stitch'||p.kind==='circuit'){cx.beginPath();for(let i=0;i<10;i++){let x=p.x-45+i*10,y=p.y+(i%2?12:-12)*(1-age);i?cx.lineTo(x,y):cx.moveTo(x,y);}cx.stroke();}else if(p.kind==='flow'||p.kind==='fold'){for(let i=0;i<4;i++){let d=(i+1)*12*age;cx.strokeRect(p.x-20-d,p.y-18-d,40+2*d,36+2*d);}}else if(p.kind==='meteor'){for(let i=0;i<5;i++){cx.beginPath();let x=p.x-40+i*20,y=p.y-70+age*110;cx.moveTo(x-12,y-30);cx.lineTo(x,y);cx.stroke();}}else if(p.kind==='verdict'||p.kind==='contract'){let r=18+age*44;cx.beginPath();for(let i=0;i<4;i++){let a=i*Math.PI/2;let x=p.x+Math.cos(a)*r,y=p.y+Math.sin(a)*r;i?cx.lineTo(x,y):cx.moveTo(x,y);}cx.closePath();cx.stroke();}else if(p.kind==='cross'){let radius=12+age*36;cx.strokeRect(p.x-radius,p.y-radius,radius*2,radius*2);cx.beginPath();cx.moveTo(p.x-radius-8,p.y);cx.lineTo(p.x+radius+8,p.y);cx.moveTo(p.x,p.y-radius-8);cx.lineTo(p.x,p.y+radius+8);cx.stroke();}else if(p.kind==='slash'){let len=32+age*90;cx.beginPath();cx.moveTo(p.x-len/2,p.y+len/3);cx.lineTo(p.x+len/2,p.y-len/3);cx.stroke();}else{cx.beginPath();cx.arc(p.x,p.y,12+age*80,0,Math.PI*2);cx.stroke();}}cx.globalAlpha=1;raf=particles.length?requestAnimationFrame(frame):0;}
function emit(p){if(reduced())return;particles.push({...p,born:performance.now(),life:p.life||650});if(particles.length>40)particles.splice(0,particles.length-40);if(!raf)raf=requestAnimationFrame(frame);}
export function syncMotion({combat,battle,phase,growth,ending}){ensure();placeMeme();document.body.dataset.motion=reduced()?'reduced':'full';root.dataset.phase=phase||'home';if(lastPhase!==phase){lastPhase=phase;if(phase==='home')cue('泰拉档案终端','连接已建立');if(phase==='ending'){cue(['阵亡','全队覆灭'].includes(ending)?'行动终止':'旅程归档','你的选择已写入泰拉档案',['阵亡','全队覆灭'].includes(ending)?'failure':'success');outcome(['阵亡','全队覆灭'].includes(ending)?'行动终止':'旅程归档',ending||'档案已保存',['阵亡','全队覆灭'].includes(ending)?'failure':'success');}if(growth?.type==='daily')cue('今日训练完成','能力提升已写入档案','success');else if(growth)cue(growth.rescued?'团队胜利 · 战后救援':'作战成功','战斗经验已写入档案','success');}
 if(!combat){clearMeme();particles=[];cx.clearRect(0,0,canvas.width,canvas.height);lastBattle=null;lastResources.clear();clearLeaders();return;}
 if(lastBattle!==battle){clearMeme();lastResources.clear();resourceFeedback(battle);clearLeaders();lastBattle=battle;seenLeaders=new Set();leaderEntrances(battle);lastAction=battle.visual?.id??-1;lastFallen=false;lastResolved=false;outcome('作战接入',battle.spec.title,'opening');cue('行动开始',battle.spec.title);document.querySelector('.arena')?.animate([{clipPath:'inset(0 0 100% 0)'},{clipPath:'inset(0)'}],{duration:reduced()?100:650,easing:'cubic-bezier(.2,.8,.2,1)'});return;}
 resourceFeedback(battle);leaderEntrances(battle);const player=battle.units.find(u=>u.isPlayer);if(player&&(player.hp<=0||player.removed)&&!lastFallen&&!battle.over){lastFallen=true;cue('博士已退场 · 观战中','存活友方继续行动，团队获胜仍算成功');}if(battle.over&&!lastResolved){lastResolved=true;outcome(battle.over.won?'作战成功':'行动结束',battle.over.won&&player?.hp<=0?'队伍完成目标 · 战后救援':battle.over.reason,battle.over.won?'success':'failure');}
 const e=battle.visual;if(!e||e.id===lastAction)return;lastAction=e.id;const now=performance.now(),m=memeFor(e);if(m)meme(m);if(now-lastBurst<130&&e.actor!=='player')return;lastBurst=now;
 let origin=bounds(e.actor);attackMotion(e,origin);let ids=e.targets.length?e.targets:[e.target],color=colorFor(e);for(let id of ids){let t=bounds(id);if(!t)continue;emit({kind:ART_MOTION[e.card]|| (e.button==='C'?'cross':'ring'),...t,color,bold:e.button==='C'});if(origin&&origin!==t)emit({kind:/799|狩猎|不再失踪/.test(e.label)?'slash':'ray',x:origin.x,y:origin.y,tx:t.x,ty:t.y,color});const el=[...document.querySelectorAll('[data-act^="target:"]')].find(v=>v.dataset.act==='target:'+id);el?.animate([{outlineColor:color,outlineOffset:'3px'},{outlineColor:'transparent',outlineOffset:'0px'}],{duration:reduced()?100:480});}
}
export function toggleMemes(){let enabled=localStorage.getItem('terra-ui-memes')==='off';localStorage.setItem('terra-ui-memes',enabled?'on':'off');if(!enabled)clearMeme();return enabled;}

export const LEADER_HOLD_MS=2000;
let leaderQueue=[],leaderLayer=null,leaderTimer=null;
export const leaderBusy=()=>!!leaderLayer||leaderQueue.length>0;
function clearLeaders(){clearTimeout(leaderTimer);leaderLayer?.remove();leaderLayer=null;leaderQueue=[];}
function showNextLeader(){if(leaderLayer||!leaderQueue.length)return;const u=leaderQueue.shift(),side='enemy';
 const layer=document.createElement('div');layer.className='leader-layer';layer.setAttribute('role','dialog');layer.setAttribute('aria-modal','true');layer.setAttribute('aria-label','敌方领袖'+'入场 · '+u.name);layer.tabIndex=0;
 const cut=document.createElement('div');cut.className='leader-cut '+side;if(u.faction){const mark=document.createElement('div');mark.className='leader-faction';mark.innerHTML=factionImage(u.faction);cut.append(mark);}
 const parts=[['small','WARNING / HOSTILE COMMAND'],['span','敌方领袖入场','leader-announcement'],['strong',u.name,'leader-name'],['span',tierLabel(numericRating(u.stats).score),'leader-grade'],['span','点击任意位置或按 Esc 关闭','leader-dismiss']];
 for(const [tag,text,cls]of parts){const el=document.createElement(tag);el.textContent=text;if(cls)el.className=cls;cut.append(el);}const line=document.createElement('div');line.className='leader-signal';line.innerHTML='<i style="width:100%"></i>';cut.append(line);layer.append(cut);document.body.append(layer);leaderLayer=layer;const previous=document.activeElement;layer.focus({preventScroll:true});
 const close=()=>{if(leaderLayer!==layer)return;clearTimeout(leaderTimer);layer.remove();leaderLayer=null;previous?.isConnected&&previous.focus({preventScroll:true});showNextLeader();};layer.addEventListener('click',close);layer.addEventListener('keydown',e=>{if(['Escape','Enter',' '].includes(e.key)){e.preventDefault();close();}else if(e.key==='Tab'){e.preventDefault();layer.focus();}});
 if(!reduced())cut.animate([{opacity:0,clipPath:'inset(0 100% 0 0)'},{opacity:1,clipPath:'inset(0)'}],{duration:180,easing:'ease-out'});leaderTimer=setTimeout(close,LEADER_HOLD_MS);
}
function leaderEntrances(b){for(const u of b.units){if(!isLeader(u)||u.removed||u.hp<=0||seenLeaders.has(u.id))continue;seenLeaders.add(u.id);leaderQueue.push({name:u.name,side:u.side,stats:structuredClone(u.stats),faction:unitFaction(u,u.cardData?.source)});}showNextLeader();}
function attackMotion(e,origin){if(!e.attack)return;const actor=document.querySelector(`[data-act="target:${e.actor}"]`);if(!reduced())actor?.animate([{transform:'translateX(0)',filter:'brightness(1)'},{transform:'translateX('+ (e.side==='ally'?6:-6)+'px)',filter:'brightness(1.25)',offset:.22},{transform:'translateX(0)',filter:'brightness(1)'}],{duration:420});
 const hits=new Map((e.impacts||[]).map(h=>[h.id,h]));for(const id of e.targets.length?e.targets:[e.target]){const target=bounds(id),node=document.querySelector(`[data-act="target:${id}"]`);if(!target)continue;const magic=e.button!=='martial',color=e.side==='enemy'?'#ef868e':magic?'#9cebf0':'#f2d3a0';if(!reduced()){emit({kind:magic?'bolt':'slash',...target,color,bold:true,life:650});if(origin)emit({kind:'shot',x:origin.x,y:origin.y,tx:target.x,ty:target.y,color,bold:true,life:480});node?.animate([{boxShadow:'inset 0 0 0 1px '+color,filter:'brightness(1)'},{boxShadow:'inset 0 0 30px '+color+'80',filter:'brightness(1.4)',offset:.2},{boxShadow:'inset 0 0 0 0 transparent',filter:'brightness(1)'}],{duration:500});}
  const hit=hits.get(id),badge=document.createElement('div');badge.className='prts-hit-number '+(e.side==='enemy'?'enemy':'ally');badge.style.left=Math.max(40,Math.min(innerWidth-70,target.x))+'px';badge.style.top=Math.max(90,Math.min(innerHeight-100,target.y-10))+'px';badge.textContent=hit&&hit.hp>0?'−'+Math.round(hit.hp):hit&&hit.shield>0?'护盾 −'+Math.round(hit.shield):'命中';if(hit?.hp>0&&hit.shield>0)badge.textContent+=' / 盾−'+Math.round(hit.shield);root.append(badge);badge.animate(reduced()?[{opacity:1},{opacity:0}]:[{opacity:0,transform:'translate(-50%,8px) scale(.85)'},{opacity:1,transform:'translate(-50%,-6px) scale(1)',offset:.15},{opacity:1,offset:.6},{opacity:0,transform:'translate(-50%,-35px)'}],{duration:reduced()?250:1000,fill:'both'});setTimeout(()=>badge.remove(),1100);
 }
}

function resourceFeedback(b){const next=new Map();for(const u of b.units)for(const r of unitResources(u,b.units)){const key=u.id+':'+r.name,old=lastResources.get(key);next.set(key,r.current);if(old===undefined||r.current===old)continue;const card=document.querySelector('[data-act="target:'+u.id+'"]');const meter=[...(card?.querySelectorAll('.unit-resource')||[])].find(el=>el.getAttribute('aria-label')===r.name+' '+r.current+'/'+r.cap);if(!meter)continue;const note=document.createElement('b');note.className='resource-delta';note.textContent=(r.current>old?'+':'')+(r.current-old);meter.append(note);if(!reduced()){meter.animate([{background:'#d2b75b70'},{background:'transparent'}],{duration:650});note.animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(-16px)'}],{duration:900,fill:'both'});}setTimeout(()=>note.remove(),950);}lastResources=next;}
